/**
 * SQL side of the private-project rule, shared by the project and issue
 * listings so a page and its `total` are cut by the same predicate.
 *
 * The service-layer twin is `canViewProject()` in `project-service`; the two
 * must stay in step. Only the non-privileged half lives here — admins, owners
 * and platform staff see everything, so their queries skip the predicate.
 */
import { and, eq, isNull, ne, notInArray, or } from "drizzle-orm";
import { getDb, projectMembers, projects } from "@/server/db";
import { orgPredicate } from "./base-repository";
import type { OrgId, UserId } from "@/types/common";
import type { SQL } from "drizzle-orm";

/**
 * True for a `projects` row that is `private` and that `userId` neither leads
 * nor has been added to. Never NULL, so it is safe to negate.
 */
export function hiddenProjectPredicate(orgId: OrgId, userId: UserId): SQL {
  const memberships = getDb()
    .select({ projectId: projectMembers.projectId })
    .from(projectMembers)
    .where(
      and(
        orgPredicate(projectMembers.orgId, orgId),
        eq(projectMembers.userId, userId),
      ),
    );

  return and(
    eq(projects.visibility, "private"),
    or(isNull(projects.leadId), ne(projects.leadId, userId)),
    notInArray(projects.id, memberships),
  ) as SQL;
}

/** Ids of the org's projects that are hidden from `userId`. */
export function hiddenProjectIds(orgId: OrgId, userId: UserId) {
  return getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, orgId),
        hiddenProjectPredicate(orgId, userId),
      ),
    );
}

