/**
 * `private` projects are invisible — not merely forbidden — to anyone who is
 * not an admin/owner, platform staff, the lead or an added project member.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let secret: Project;
let secretIssue: Issue;
let secretComment: Comment;
let openIssue: Issue;

/** A `member`-role actor who is neither lead nor added to the project. */
let outsider: Actor;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privacy");
  outsider = tenant.actors.member;

  secret = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: "Secret",
    slug: "secret",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: tenant.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });

  secretIssue = await issueService.createIssue(
    tenant.actors.admin,
    issueInput(tenant.org.id, secret.id, { title: "Hidden work" }),
  );
  secretComment = await commentService.createComment(tenant.actors.admin, {
    orgId: tenant.org.id,
    issueId: secretIssue.id,
    body: "for admins only",
    parentId: null,
    mentionedUserIds: [],
  });
  openIssue = await issueService.createIssue(
    outsider,
    issueInput(tenant.org.id, tenant.project.id, { title: "Public work" }),
  );
});

afterAll(() => {
  cleanup();
});

describe("canViewProject", () => {
  it("lets everyone see org and public projects", async () => {
    for (const visibility of ["org", "public"] as const) {
      const project = { ...secret, visibility };
      expect(await projectService.canViewProject(outsider, project)).toBe(true);
      expect(await projectService.canViewProject(tenant.actors.viewer, project)).toBe(true);
    }
  });

  it("admits admin, owner, platform staff and the lead", async () => {
    expect(await projectService.canViewProject(tenant.actors.admin, secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.owner, secret)).toBe(true);
    expect(
      await projectService.canViewProject({ ...outsider, isPlatformStaff: true }, secret),
    ).toBe(true);
    expect(
      await projectService.canViewProject(outsider, { ...secret, leadId: outsider.userId }),
    ).toBe(true);
  });

  it("refuses members and viewers who are not on the project", async () => {
    expect(await projectService.canViewProject(outsider, secret)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(false);
  });
});

describe("private project — reads and writes by an outsider", () => {
  it("throws NotFoundError for the project, issue, board and thread", async () => {
    const { org } = tenant;
    await expect(projectService.getProject(outsider, org.id, "secret")).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getIssue(outsider, org.id, secretIssue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(issueService.getBoard(outsider, org.id, secret.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.getThread(outsider, org.id, secretIssue.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(attachmentService.listAttachments(outsider, org.id, secretIssue.id)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("throws NotFoundError for every write and changes nothing", async () => {
    const { org } = tenant;
    const attempts = [
      () => issueService.createIssue(outsider, issueInput(org.id, secret.id)),
      () => issueService.updateIssue(outsider, { orgId: org.id, issueId: secretIssue.id, title: "pwned" }),
      () => issueService.changeIssueStatus(outsider, { orgId: org.id, issueId: secretIssue.id, status: "done" }),
      () =>
        issueService.moveIssue(outsider, {
          orgId: org.id,
          issueId: secretIssue.id,
          toStatus: "done",
          toIndex: 0,
        }),
      () => issueService.assignIssue(outsider, { orgId: org.id, issueId: secretIssue.id, assigneeId: outsider.userId }),
      () => issueService.archiveIssue(outsider, org.id, secretIssue.id),
      () =>
        commentService.createComment(outsider, {
          orgId: org.id,
          issueId: secretIssue.id,
          body: "hello?",
          parentId: null,
          mentionedUserIds: [],
        }),
      () => commentService.updateComment(outsider, { orgId: org.id, commentId: secretComment.id, body: "edited" }),
      () => commentService.deleteComment(outsider, { orgId: org.id, commentId: secretComment.id }),
      () => projectService.updateProject(outsider, { orgId: org.id, projectId: secret.id, name: "pwned" }),
      () => projectService.archiveProject(outsider, { orgId: org.id, projectId: secret.id, archiveIssues: true }),
      () => projectService.restoreProject(outsider, org.id, secret.id),
    ];

    for (const attempt of attempts) {
      await expect(attempt()).rejects.toBeInstanceOf(NotFoundError);
    }

    const issue = await issueRepo.findIssueById(org.id, secretIssue.id);
    expect(issue).toMatchObject({ title: "Hidden work", status: "backlog", assigneeId: null, archivedAt: null });
    const comment = await commentRepo.findCommentById(org.id, secretComment.id);
    expect(comment).toMatchObject({ body: "for admins only", archivedAt: null });
    const project = await projectRepo.findProjectById(org.id, secret.id);
    expect(project).toMatchObject({ name: "Secret", archivedAt: null });
    expect(await issueRepo.countIssues(org.id, secret.id, { includeArchived: true })).toBe(1);
  });

  it("silently omits the project and its issues from listings, and from their totals", async () => {
    const { org } = tenant;

    const projects = await projectService.listProjects(outsider, { orgId: org.id, limit: 50 });
    expect(projects.items.map((row) => row.project.slug)).toEqual(["platform"]);
    expect(projects.total).toBe(1);

    const issues = await issueService.listIssues(outsider, { orgId: org.id, limit: 50 });
    expect(issues.items.map((issue) => issue.id)).toEqual([openIssue.id]);
    expect(issues.total).toBe(1);

    const scoped = await issueService.listIssues(outsider, { orgId: org.id, limit: 50, projectId: secret.id });
    expect(scoped.items).toEqual([]);
    expect(scoped.total).toBe(0);
  });

  it("keeps a page and its cursor consistent while hiding rows", async () => {
    const { org } = tenant;
    const first = await issueService.listIssues(outsider, { orgId: org.id, limit: 1 });
    expect(first.items).toHaveLength(1);
    expect(first.nextCursor).toBeNull();
    expect(first.total).toBe(1);
  });
});

describe("private project — who does see it", () => {
  it("shows everything to admins, owners and staff", async () => {
    const { org } = tenant;
    for (const actor of [tenant.actors.admin, tenant.actors.owner, { ...outsider, isPlatformStaff: true }]) {
      const projects = await projectService.listProjects(actor, { orgId: org.id, limit: 50 });
      expect(projects.total).toBe(2);
      const issues = await issueService.listIssues(actor, { orgId: org.id, limit: 50 });
      expect(issues.total).toBe(2);
      await expect(issueService.getIssue(actor, org.id, secretIssue.id)).resolves.toMatchObject({
        issue: { id: secretIssue.id },
      });
      await expect(commentService.getThread(actor, org.id, secretIssue.id)).resolves.toHaveLength(1);
    }
  });

  it("applies a change of project membership immediately", async () => {
    const { org } = tenant;
    await expect(issueService.getIssue(outsider, org.id, secretIssue.id)).rejects.toBeInstanceOf(NotFoundError);

    await projectMemberRepo.addProjectMember(org.id, secret.id, outsider.userId);
    expect((await projectService.getProject(outsider, org.id, "secret")).project.id).toBe(secret.id);
    expect((await issueService.listIssues(outsider, { orgId: org.id, limit: 50 })).total).toBe(2);
    expect((await projectService.listProjects(outsider, { orgId: org.id, limit: 50 })).total).toBe(2);
    await expect(
      issueService.updateIssue(outsider, { orgId: org.id, issueId: secretIssue.id, title: "Now allowed" }),
    ).resolves.toMatchObject({ title: "Now allowed" });

    await projectMemberRepo.removeProjectMember(org.id, secret.id, outsider.userId);
    await expect(issueService.getBoard(outsider, org.id, secret.id)).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueService.listIssues(outsider, { orgId: org.id, limit: 50 })).total).toBe(1);
  });

  it("applies a change of lead immediately", async () => {
    const { org } = tenant;
    await projectRepo.updateProject({ orgId: org.id, projectId: secret.id, leadId: outsider.userId });
    expect((await projectService.getProject(outsider, org.id, "secret")).project.id).toBe(secret.id);
    expect((await issueService.listIssues(outsider, { orgId: org.id, limit: 50 })).total).toBe(2);

    await projectRepo.updateProject({ orgId: org.id, projectId: secret.id, leadId: tenant.userIds.owner });
    await expect(projectService.getProject(outsider, org.id, "secret")).rejects.toBeInstanceOf(NotFoundError);
    expect((await issueService.listIssues(outsider, { orgId: org.id, limit: 50 })).total).toBe(1);
  });

  it("stops hiding the project once it is no longer private", async () => {
    const { org } = tenant;
    await projectRepo.updateProject({ orgId: org.id, projectId: secret.id, visibility: "org" });
    expect((await issueService.getIssue(outsider, org.id, secretIssue.id)).issue.id).toBe(secretIssue.id);
    await projectRepo.updateProject({ orgId: org.id, projectId: secret.id, visibility: "private" });
  });
});

